      SUBROUTINE RBVGETCC     HIGHER-ORDER AND NON-MIDPLANE-SYMMETRIC COMPONENTS FORC     CENTRAL FIELD OF RBEND AND SBENDCC ----------------------------------------------------------------------      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4C.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16A.CIN'      INCLUDE 'ELM26B.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'XRAN.CIN'CC     LOCAL VARIABLESC      INTEGER         IADR, IBDB, IBDBP, IGAM, IK1P, IK2, IK2P, IK3      INTEGER         INP, IRNMS, IVR      REAL            DATARC-------------------------------------------------------------------------------CC     INDICES FOR PARAMETERSC      NRNMS = 8      NVR = 9      NNP = 10      NK1P = 11      NBDB = 14      NK2 = 15      NBDBP = 16      NK2P = 17      NGAM = 20      NK3 = 21CC     NORMALIZED VERTICAL BENDC      IVR = IPTOJ(NVR)      IF (IVR .NE. 0) THEN        IADR = I + IVR        VRN = DATAR(IADR)      ELSE        VRN = VRNI      ENDIF      IF (PRAN28(NVR) .NE. 0.0)     1    VRN = VRN + PRAN28(NVR)*XRAN(NVR)CC     NORMALIZED NON-MIDPLANE-SYMMETRIC GRADIENTC      INP = IPTOJ(NNP)      IK1P = IPTOJ(NK1P)      IF (IK1P .EQ. 0 .AND. PRAN28(NK1P) .EQ. 0.0) THEN        IF (INP .EQ. 0) THEN          NPN = NPNI        ELSE          IADR = I + INP          NPN = DATAR(IADR)        ENDIF        IF (PRAN28(NNP) .NE. 0.0) NPN = NPN + PRAN28(NNP)*XRAN(NNP)      ELSE         IF (IK1P .EQ. 0) THEN          K1P = 0.0        ELSE          IADR = I + IK1P          K1P = DATAR(IADR)        ENDIF        IF (PRAN28(NK1P) .NE. 0.0) K1P = K1P + PRAN28(NK1P)*XRAN(NK1P)        K1P = K1P/UNITI(8)**2        IF (H0 .NE. 0.0) NPN = - K1P/H0**2      ENDIFCC     SCALING FACTOR FOR NON-MIDPLANE-SYMMETRIC COMPONENTSC      IRNMS = IPTOJ(NRNMS)      IF (IRNMS .NE. 0) THEN        IADR = I + IRNMS        RNMS = DATAR(IADR)      ELSE        RNMS = RNMSI      ENDIF      IF (PRAN28(NRNMS) .NE. 0.0)     1    RNMS = RNMS + PRAN28(NRNMS)*XRAN(NRNMS)CC     NORMALIZED FIELD SECOND DERIVATIVEC      IBDB = IPTOJ(NBDB)      IK2 = IPTOJ(NK2)      IF (IBDB .NE. 0) THEN        IADR = I + IBDB        BDB = DATAR(IADR)        IF (PRAN28(NBDB) .NE. 0.0) BDB = BDB + PRAN28(NBDB)*XRAN(NBDB)      ELSE IF (IK2 .NE. 0) THEN        IADR = I + IK2        K2 = DATAR(IADR)        IF (PRAN28(NK2) .NE. 0.0)     1      K2 = K2 + PRAN28(NK2)*XRAN(NK2)        IF (MPMAD) K2 = 0.5*K2        K2 = K2/UNITI(8)**3        BDB = K2*UNITI(1)**2/H0      ELSE        BDB = BDBI        IF (PRAN28(NBDB) .NE. 0.0) BDB = BDB + PRAN28(NBDB)*XRAN(NBDB)      ENDIFCC     NORMALIZED NON-MIDPLANE-SYMMETRIC FIELD SECOND DERIVATIVEC      IBDBP = IPTOJ(NBDBP)      IK2P = IPTOJ(NK2P)      IF (IK2P .EQ. 0 .AND. PRAN28(NK2P) .EQ. 0.0) THEN        IF (IBDBP .EQ. 0) THEN          BDBP = BDBPI        ELSE          IADR = I + IBDBP          BDBP = DATAR(IADR)        ENDIF        IF (PRAN28(NBDBP) .NE. 0.0)     1      BDBP = BDBP + PRAN28(NBDBP)*XRAN(NBDBP)      ELSE         IF (IK2P .EQ. 0) THEN          K2P = 0.0        ELSE          IADR = I + IK2P          K2P = DATAR(IADR)        ENDIF        IF (PRAN28(NK2P) .NE. 0.0) K2P = K2P + PRAN28(NK2P)*XRAN(NK2P)        IF (MPMAD) K2P = 0.5*K2P        K2P = K2P/UNITI(8)**3        IF (H0 .NE. 0.0) BDBP = K2P*UNITI(1)**2/H0      ENDIFCC     NORMALIZED FIELD THIRD DERIVATIVEC      IGAM = IPTOJ(NGAM)      IK3 = IPTOJ(NK3)      IF (IGAM .NE. 0) THEN        IADR = I + IGAM        GAM = DATAR(IADR)        IF (PRAN28(IGAM) .NE. 0.0) GAM = GAM + PRAN28(IGAM)*XRAN(IGAM)      ELSE IF (IK3 .NE. 0) THEN        IADR = I + IK3        K3 = DATAR(IADR)        IF (MPMAD) K3 = K3/6.0        K3 = K3/UNITI(8)**4        GAM = K3*UNITI(1)**3/H0      ELSE        GAM = GAMI        IF (PRAN28(NGAM) .NE. 0.0) GAM = GAM + PRAN28(NGAM)*XRAN(NGAM)      ENDIF      RETURN      END